<?php
require_once 'config.php';
if (admin_count()===0) { header('Location: setup_admin.php'); exit; }
require_login();
$pdo=db(); $admin=current_admin();
$products=$pdo->query("SELECT * FROM products ORDER BY name")->fetchAll();
$totalProducts=(int)$pdo->query("SELECT COUNT(*) FROM products")->fetchColumn();
$totalUnits=(int)$pdo->query("SELECT COALESCE(SUM(quantity),0) FROM products")->fetchColumn();
$lowStock=(int)$pdo->query("SELECT COUNT(*) FROM products WHERE quantity<=min_stock")->fetchColumn();
$expiring=(int)$pdo->query("SELECT COUNT(*) FROM products WHERE expiry_date IS NOT NULL AND expiry_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 7 DAY)")->fetchColumn();
$todaySales=(float)$pdo->query("SELECT COALESCE(SUM(quantity*unit_price),0) FROM sales WHERE DATE(sold_at)=CURDATE()")->fetchColumn();
$recentSales=$pdo->query("SELECT s.*,p.name FROM sales s JOIN products p ON p.id=s.product_id ORDER BY s.sold_at DESC LIMIT 10")->fetchAll();
$notice=$_GET['notice']??''; $search=trim($_GET['q']??'');
if($search!==''){ $st=$pdo->prepare("SELECT * FROM products WHERE name LIKE ? OR category LIKE ? ORDER BY name"); $like='%'.$search.'%'; $st->execute([$like,$like]); $products=$st->fetchAll(); }
$alerts=$pdo->query("SELECT *,DATEDIFF(expiry_date,CURDATE()) days_left FROM products WHERE quantity<=min_stock OR (expiry_date IS NOT NULL AND expiry_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 7 DAY)) ORDER BY expiry_date ASC LIMIT 7")->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SmartInventory | Shop dashboard</title><link rel="stylesheet" href="style.css"></head><body>
<aside class="sidebar"><div class="brand"><span class="brand-icon">▦</span><div>Smart<span>Inventory</span><small>SHOP MANAGEMENT</small></div></div><nav><a class="active" href="index.php">▦ &nbsp; Overview</a><a href="#products">▤ &nbsp; Products</a><a href="#sales">↗ &nbsp; Sales</a><a href="#insights">✦ &nbsp; AI Insights</a><a href="#history">▧ &nbsp; Sales history</a></nav><a class="side-bottom side-profile" href="profile.php"><div class="avatar"><?=e(mb_substr($admin['full_name'],0,1))?></div><div><b><?=e($admin['full_name'])?></b><small>Admin profile · Logout in profile</small></div></a></aside>
<main class="main"><header class="topbar"><div><p class="eyebrow">INVENTORY / OVERVIEW</p><h1>Good day, <?=e($admin['full_name'])?> 👋</h1><p class="muted">Here's what's happening in your store today.</p></div><div class="date-pill"><?=date('D, d M Y')?></div></header>
<?php if($notice): ?><div class="notice"><?=e($notice)?></div><?php endif; ?>
<section class="stats"><div class="stat-card"><div class="stat-top"><span>Total products</span><span class="stat-icon purple">▤</span></div><strong><?=$totalProducts?></strong><small>Products in catalogue</small></div><div class="stat-card"><div class="stat-top"><span>Units in stock</span><span class="stat-icon blue">▦</span></div><strong><?=$totalUnits?></strong><small>Across all products</small></div><div class="stat-card"><div class="stat-top"><span>Low stock alerts</span><span class="stat-icon orange">!</span></div><strong><?=$lowStock?></strong><small>Need replenishment</small></div><div class="stat-card"><div class="stat-top"><span>Expiring soon</span><span class="stat-icon red">◷</span></div><strong><?=$expiring?></strong><small>Within next 7 days</small></div></section>
<section class="grid-two"><div class="panel" id="products"><div class="panel-head"><div><h2>Product inventory</h2><p class="muted">Manage stock, prices and expiry dates.</p></div><button class="primary" onclick="document.getElementById('addForm').classList.toggle('hidden')">＋ Add product</button></div>
<form method="get" class="search-form"><input name="q" value="<?=e($search)?>" placeholder="Search product or category"><button class="secondary">Search</button><?php if($search!==''): ?><a class="text-link" href="index.php">Clear</a><?php endif; ?></form>
<form id="addForm" class="add-form hidden" method="post" action="save_product.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input name="name" placeholder="Product name" required><input name="category" placeholder="Category"><input name="quantity" type="number" min="0" placeholder="Quantity" required><input name="min_stock" type="number" min="0" placeholder="Min. stock" value="5"><input name="price" type="number" step="0.01" min="0" placeholder="Selling price" required><input name="cost_price" type="number" step="0.01" min="0" placeholder="Cost price" required><label class="date-label">Expiry date <input name="expiry_date" type="date"></label><button class="primary" type="submit">Save product</button></form>
<div class="table-wrap"><table><thead><tr><th>PRODUCT</th><th>STOCK</th><th>PRICE</th><th>EXPIRY</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody><?php foreach($products as $p):
$days=$p['expiry_date']?(int)$pdo->query("SELECT DATEDIFF(".$pdo->quote($p['expiry_date']).",CURDATE())")->fetchColumn():null;
$status=($p['quantity']<=$p['min_stock'])?'Low stock':(($days!==null&&$days<=7&&$days>=0)?'Expiring':'Healthy'); $cls=$status==='Low stock'?'warning':($status==='Expiring'?'danger':'success'); ?>
<tr><td><b><?=e($p['name'])?></b><small><?=e($p['category'])?></small></td><td><?=$p['quantity']?> units</td><td>₹<?=number_format((float)$p['price'],2)?></td><td><?=$p['expiry_date']?date('d M Y',strtotime($p['expiry_date'])):'—'?></td><td><span class="badge <?=$cls?>"><?=e($status)?></span></td><td class="actions"><a class="edit-link" href="edit_product.php?id=<?=$p['id']?>">Edit</a><form method="post" action="delete_product.php" onsubmit="return confirm('Delete this product?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="icon-btn" title="Delete">×</button></form></td></tr><?php endforeach; if(!$products): ?><tr><td colspan="6" class="empty">No products found. Add a product or clear your search.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="right-col"><div class="panel"><div class="panel-head"><div><h2>Quick alerts</h2><p class="muted">Items that need your attention.</p></div></div><?php foreach($alerts as $a): ?><div class="alert-row"><span class="alert-dot <?=$a['quantity']<=$a['min_stock']?'orange-dot':'red-dot'?>"></span><div><b><?=e($a['name'])?></b><small><?=$a['quantity']<=$a['min_stock']?'Only '.$a['quantity'].' units left':'Expires in '.$a['days_left'].' day(s)'?></small></div></div><?php endforeach; if(!$alerts): ?><p class="empty">All clear. No urgent alerts.</p><?php endif; ?></div>
<div class="panel" id="sales"><div class="panel-head"><div><h2>Record a sale</h2><p class="muted">Stock automatically decreases after a sale.</p></div></div><form method="post" action="record_sale.php" class="sale-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><select name="product_id" required><option value="">Select product</option><?php foreach($pdo->query("SELECT id,name,quantity FROM products WHERE quantity>0 ORDER BY name") as $p): ?><option value="<?=$p['id']?>"><?=e($p['name'])?> (<?=$p['quantity']?>)</option><?php endforeach; ?></select><input type="number" name="quantity" min="1" placeholder="Quantity sold" required><button class="primary full">Record sale</button></form><div class="revenue"><small>Today's recorded sales</small><strong>₹<?=number_format($todaySales,2)?></strong></div></div></div></section>
<section class="panel insights" id="insights"><div class="panel-head"><div><h2>✦ Smart store assistant</h2><p class="muted">Get AI-generated action suggestions based on your current inventory.</p></div><button class="secondary" id="insightBtn">Generate insights</button></div><div id="insightOutput" class="insight-output">Your inventory assistant is ready. Generate insights when you need a stock review.</div></section>
<section class="panel" id="history"><div class="panel-head"><div><h2>Sales history</h2><p class="muted">Latest recorded transactions.</p></div></div><div class="table-wrap"><table><thead><tr><th>PRODUCT</th><th>QUANTITY</th><th>UNIT PRICE</th><th>TOTAL</th><th>DATE</th></tr></thead><tbody><?php foreach($recentSales as $s): ?><tr><td><b><?=e($s['name'])?></b></td><td><?=$s['quantity']?></td><td>₹<?=number_format((float)$s['unit_price'],2)?></td><td>₹<?=number_format((float)$s['quantity']*(float)$s['unit_price'],2)?></td><td><?=date('d M Y, h:i A',strtotime($s['sold_at']))?></td></tr><?php endforeach; if(!$recentSales): ?><tr><td colspan="5" class="empty">No sales recorded yet.</td></tr><?php endif; ?></tbody></table></div></section>
<footer>SmartInventory · Built for smarter local retail management</footer></main><script src="app.js"></script></body></html>
